/**
 * Video Studio › Sản xuất: script-first video production with KOLs.
 *
 *   brief → script & storyboard (written in the KOL's voice) → scenes generated by an engine
 *   (HeyGen talking head, Veo / fal clips through KOL Studio, RocketFlow, or an existing clip)
 *   → assembled into one A-roll → handed to the HyperFrames editor for captions, hook, effects, music, covers.
 *
 * KOL Studio owns the characters (faces, refs, voice, profile). Video Studio only reads them and asks
 * KOL Studio to render identity-locked media, so spend caps and identity checks always apply.
 */

import type { VideoAspect } from '../types.js';

export type SceneKind = 'talking' | 'broll' | 'clip';

/**
 * heygen    talking head from a KOL image + script + HeyGen voice (lip-synced, any length)
 * veo       Google Veo through KOL Studio (talking ≤ 8 s with native speech, or an animated KOL shot)
 * fal       fal.ai video model through KOL Studio (animated KOL shot) or text-to-video b-roll
 * rocketflow Google Flow through the RocketFlow extension (b-roll)
 * stock     a licence-free stock clip from Pexels (b-roll, free)
 * clip      an existing video (KOL gallery or upload): no generation
 */
export type SceneEngine = 'heygen' | 'veo' | 'fal' | 'rocketflow' | 'stock' | 'clip';

export type SceneStatus = 'draft' | 'queued' | 'running' | 'done' | 'failed';

export interface ProductionScene {
  id: string;
  kind: SceneKind;
  /** KOL in the shot (talking scenes always have one). */
  kolId: string | null;
  /** Spoken line (talking) or optional voice-over idea (b-roll). */
  text: string;
  /** Visual direction: setting, action, camera (any language). */
  visual: string;
  engine: SceneEngine;
  /** Engine model id when the engine has several (e.g. a fal model). */
  model: string | null;
  /** KOL image asset used as the face / start frame. */
  sourceAssetId: string | null;
  /** Existing video for engine 'clip' (KOL asset id). */
  clipAssetId: string | null;
  /** Wanted length in seconds (talking scenes follow the speech). */
  durationSec: number;
  /** Where the take starts inside the source file (seconds). Trimming never regenerates. */
  trimStart?: number;
  /** Approved takes so far: a retake is a new provider request (idempotency key, next stock result). */
  take?: number;
  /** Provider overloaded ("high demand"): nothing was generated, the approved scene retries by itself at `at`. */
  retry?: { n: number; at: string } | null;
  status: SceneStatus;
  /** Provider job handle while queued/running. */
  job: { provider: string; ref: string; startedAt: string } | null;
  /** durationSec: the part that plays (after trim); sourceSec: the whole file. */
  output: { file: string; durationSec: number; sourceSec?: number; subtitles: string | null; thumb: string | null; credit?: string } | null;
  error: string | null;
  updatedAt: string;
}

export type ProductionState = 'brief' | 'storyboard' | 'generating' | 'ready' | 'assembling' | 'finishing' | 'failed';

export interface ProductionScript {
  title: string;
  hook: string;
  caption: string;
  hashtags: string[];
}

export interface CostLine {
  sceneId: string;
  engine: SceneEngine;
  seconds: number;
  /** USD for API engines; null when the model has no price yet. */
  usd: number | null;
  /** HeyGen plan credits (estimate). */
  credits: number | null;
  note: string;
}

export interface CostEstimate {
  usd: number;
  /** Scenes whose model has no price (shown as "chưa có giá"). */
  unpriced: number;
  heygenCredits: number;
  /** RocketFlow scenes (Google Flow credits of the owner's plan). */
  flowScenes: number;
  /** Stock or existing clips. */
  freeScenes: number;
  lines: CostLine[];
}

export interface PendingApproval {
  approvalId: string;
  sceneIds: string[];
  fingerprint: string;
  estimate: CostEstimate;
  createdAt: string;
}

export interface Production {
  id: string;
  /** Host VideoProject (mode 'produce'): chat, agent turns, finishing and export all live there. */
  projectId: string | null;
  /** Batch of scenes waiting for the owner's spend approval. */
  pendingApproval: PendingApproval | null;
  /** Series this video belongs to (one idea → several videos). */
  series?: { id: string; index: number; total: number; angle: string } | null;
  title: string;
  /** The owner named the video: the script writer keeps this title. */
  titleLocked?: boolean;
  /** KOL ids mentioned with @ (first = lead). */
  cast: string[];
  brief: string;
  aspect: VideoAspect;
  targetSec: number;
  script: ProductionScript | null;
  scenes: ProductionScene[];
  state: ProductionState;
  /** Edit project the A-roll was handed to (HyperFrames finishing). */
  finishProjectId: string | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export type ProductionSummary = Pick<Production, 'id' | 'title' | 'cast' | 'aspect' | 'targetSec' | 'state' | 'finishProjectId' | 'projectId' | 'series' | 'createdAt' | 'updatedAt'> & {
  pendingApproval: boolean;
  scenes: number;
  scenesDone: number;
  thumb: string | null;
};

export interface EngineStatus {
  id: SceneEngine | 'hyperframes' | 'whisper' | 'elevenlabs';
  label: string;
  /** What the engine is for, in one line. */
  role: string;
  ready: boolean;
  detail: string;
  /** Where to fix it when not ready. */
  fix: string | null;
}

/** Per-KOL production settings kept by Video Studio (KOL Studio stays the source of the character). */
export interface KolVoice {
  provider: 'heygen';
  voiceId: string;
  name: string;
}

export interface CastMember {
  id: string;
  name: string;
  handle: string;
  avatarUrl: string | null;
  tagline: string;
  status: string;
  /** Approved images usable as the face / start frame, newest first. */
  images: { id: string; url: string; thumbUrl: string | null; width: number | null; height: number | null }[];
  /** Existing videos in the KOL gallery. */
  videos: { id: string; url: string; thumbUrl: string | null; durationSec: number | null }[];
  voice: KolVoice | null;
  /** A real, licensed person (KOL Studio identity_source 'licensed'): Veo refuses real likenesses. */
  realPerson?: boolean;
}

export const SCENE_KINDS: SceneKind[] = ['talking', 'broll', 'clip'];
export const SCENE_ENGINES: SceneEngine[] = ['heygen', 'veo', 'fal', 'rocketflow', 'stock', 'clip'];

/** Engines that make each kind of scene, best first. */
export const ENGINES_FOR: Record<SceneKind, SceneEngine[]> = {
  talking: ['heygen', 'veo', 'rocketflow'],
  broll: ['veo', 'fal', 'rocketflow', 'stock'],
  clip: ['clip'],
};

/** Per-KOL brand kit kept by Video Studio: applied by the writer, the director and the finishing step. */
export interface KolBrand {
  /** Default finishing style (VIDEO_STYLES id). */
  styleId: string | null;
  /** Closing call to action the KOL always uses (e.g. "Bình luận HỆ THỐNG"). */
  cta: string;
  /** Opening line or tag (optional). */
  intro: string;
  /** Sign-off line (optional). */
  outro: string;
  /** Caption look in the owner's words (e.g. "chữ to, vàng ở từ khoá"). */
  captionNote: string;
  /** Background music: let the director pick, or none. */
  music: 'auto' | 'none';
}

export const DEFAULT_BRAND: KolBrand = { styleId: null, cta: '', intro: '', outro: '', captionNote: '', music: 'auto' };

/** Veo clips are capped at 8 s. */
export const VEO_MAX_SEC = 8;
